adcs_status_t status;
adcs_vec3_t h_body = {0};
adcs_vec3_t h_parallel = {0};
adcs_vec3_t h_perp = {0};
double b_norm_sq = 0.0;
double b_norm = 0.0;
double h_perp_mag = 0.0;
int valid_config = 1;
int valid_inputs = 1;

// 1. Validate Inputs
if (wd_input.enable != 0 && wd_input.enable != 1) {
    valid_inputs = 0;
}

if (wd_input.wheel_count != 4) {
    valid_config = 0;
}

if (!isfinite(wd_config.start_nms) || !isfinite(wd_config.stop_nms) ||
    !isfinite(wd_config.gain_s_inv) || !isfinite(wd_config.max_dipole_a_m2) ||
    !isfinite(wd_config.max_wheel_speed_rad_s)) {
    valid_config = 0;
} else {
    if (wd_config.start_nms < 0.0 || wd_config.stop_nms < 0.0 ||
        wd_config.gain_s_inv < 0.0 || wd_config.max_dipole_a_m2 < 0.0 ||
        wd_config.max_wheel_speed_rad_s <= 0.0) {
        valid_config = 0;
    } else if (!(wd_config.stop_nms < wd_config.start_nms)) {
        valid_config = 0;
    }

    if (wd_config.required_high < 1 || wd_config.required_high > 100 ||
        wd_config.required_low < 1 || wd_config.required_low > 100 ||
        wd_config.minimum_dump_cycles < 1 || wd_config.minimum_dump_cycles > 100 ||
        wd_config.cooldown_cycles < 1 || wd_config.cooldown_cycles > 100) {
        valid_config = 0;
    }
}

if (wd_input.field_body_t == NULL || !adcs_is_finite_vec3(wd_input.field_body_t)) {
    valid_inputs = 0;
} else {
    b_norm_sq = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
    if (sqrt(b_norm_sq) <= ADCS_EPS_NORM) {
        valid_inputs = 0;
    }
}

if (valid_inputs && valid_config) {
    for (size_t i = 0; i < 4; i++) {
        if (!isfinite(wd_input.wheels[i].speed_rad_s) ||
            fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s) {
            valid_inputs = 0;
            break;
        }
    }
}

// 2. Handle Fault / Disable
if (!valid_inputs || !valid_config) {
    wd_state.mode = WD_FAULT;
    wd_output.mode = WD_FAULT;
    wd_output.momentum_nms = (adcs_vec3_t){0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0};
    wd_output.torque_nm = (adcs_vec3_t){0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

if (wd_input.enable == 0) {
    wd_state.mode = WD_OFF;
    wd_state.high_cycles = 0;
    wd_state.low_cycles = 0;
    wd_state.elapsed = 0;
}

// 3. Compute Momentum
status = adcs_wheel_momentum(wd_input.wheels, 4, &h_body);
if (status != ADCS_OK || !adcs_is_finite_vec3(&h_body)) {
    wd_state.mode = WD_FAULT;
    wd_output.mode = WD_FAULT;
    wd_output.momentum_nms = (adcs_vec3_t){0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0};
    wd_output.torque_nm = (adcs_vec3_t){0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

// 4. Decompose Momentum
b_norm = sqrt(b_norm_sq);
double dot_hp_b = adcs_vec3_dot(&h_body, wd_input.field_body_t);
double parallel_coeff = dot_hp_b / b_norm_sq;
h_parallel = adcs_vec3_scale(wd_input.field_body_t, parallel_coeff);
h_perp = adcs_vec3_sub(&h_body, &h_parallel);
h_perp_mag = adcs_vec3_norm(&h_perp);

// Publish Momentum Data
wd_output.momentum_nms = h_body;
wd_output.parallel_momentum_nms = h_parallel;
wd_output.dumpable_momentum_nms = h_perp;
wd_output.dumpable_magnitude_nms = h_perp_mag;

// 5. State Machine
switch (wd_state.mode) {
    case WD_OFF:
        if (h_perp_mag >= wd_config.start_nms) {
            wd_state.high_cycles++;
        } else {
            wd_state.high_cycles = 0;
        }

        if (wd_state.high_cycles >= wd_config.required_high) {
            wd_state.mode = WD_ARMING;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
        }

        wd_output.mode = wd_state.mode;
        wd_output.high_cycles = wd_state.high_cycles;
        wd_output.low_cycles = 0;
        wd_output.elapsed = 0;
        wd_output.dipole_a_m2 = (adcs_vec3_t){0};
        wd_output.torque_nm = (adcs_vec3_t){0};
        wd_output.saturation_mask = 0;
        break;

    case WD_ARMING:
        wd_state.mode = WD_DUMPING;
        wd_state.high_cycles = 0;
        wd_state.low_cycles = 0;
        wd_state.elapsed = 0;
        // Fall through to DUMPING logic? No, need to generate command for THIS cycle?
        // "Entering DUMPING ... resets ... (the entry call publishes elapsed 0)".
        // Does the entry call generate a command? Yes, "Generate commands ... and report".
        // So we treat Arming->DUMPING transition as entering Dumping state.
        // We need to execute Dumping logic for this call.
        // To avoid code duplication, let's just set mode and continue to logic below,
        // but we must ensure elapsed is 0 for this call.
        // Since we are in a switch, we can't easily fall through to another case block 
        // without jumping or duplicating.
        // Let's duplicate the command generation part or structure differently.
        // Better: Set state, then execute common command gen logic for Dumping.

        wd_output.mode = WD_DUMPING;
        wd_output.high_cycles = 0;
        wd_output.low_cycles = 0;
        wd_output.elapsed = 0;

        // Execute Dumping Command Generation
        {
            adcs_actuator_command_t cmd;
            status = adcs_momentum_unload_dipole(&h_perp, wd_input.field_body_t,
                                                 wd_config.gain_s_inv, wd_config.max_dipole_a_m2,
                                                 &cmd, &wd_output.torque_nm);
            wd_output.dipole_a_m2 = cmd.command;
            wd_output.saturation_mask = cmd.saturated_axes;
        }

        // Check Stop Condition (Elapsed is 0, so < min_dump_cycles, no low count)
        wd_output.low_cycles = 0;
        break;

    case WD_DUMPING:
        // Increment elapsed if not entry call
        if (wd_state.elapsed > 0) {
            wd_state.elapsed++;
        }

        wd_output.mode = WD_DUMPING;
        wd_output.elapsed = wd_state.elapsed;
        wd_output.high_cycles = 0;

        // Generate Command
        {
            adcs_actuator_command_t cmd;
            status = adcs_momentum_unload_dipole(&h_perp, wd_input.field_body_t,
                                                 wd_config.gain_s_inv, wd_config.max_dipole_a_m2,
                                                 &cmd, &wd_output.torque_nm);
            wd_output.dipole_a_m2 = cmd.command;
            wd_output.saturation_mask = cmd.saturated_axes;
        }

        // Check Stop Condition
        if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
            if (h_perp_mag <= wd_config.stop_nms) {
                wd_state.low_cycles++;
            } else {
                wd_state.low_cycles = 0;
            }
        }

        wd_output.low_cycles = wd_state.low_cycles;

        if (wd_state.low_cycles >= wd_config.required_low) {
            wd_state.mode = WD_COOLDOWN;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
            // Will handle COOLDOWN output in next iteration or force update?
            // We need to update output to COOLDOWN state for THIS call?
            // "Entering ... resets ...".
            // The output should reflect the NEW state? Or the state during the call?
            // Usually state machines update state at end of step, or beginning.
            // Here, we are computing output for the current step.
            // If we transition, the output should probably show the new state?
            // Or the old state?
            // "report the returned achievable torque...".
            // If we transition to Cooldown, do we report Cooldown torque (zero)?
            // Yes, "COOLDOWN commands zero".
            // So if we detect transition, we should output Cooldown values.
            wd_output.mode = WD_COOLDOWN;
            wd_output.dipole_a_m2 = (adcs_vec3_t){0};
            wd_output.torque_nm = (adcs_vec3_t){0};
            wd_output.saturation_mask = 0;
            wd_output.elapsed = 0; // Entry call for Cooldown
            wd_output.low_cycles = 0;
            wd_output.high_cycles = 0;
        }
        break;

    case WD_COOLDOWN:
        if (wd_state.elapsed > 0) {
            wd_state.elapsed++;
        }

        wd_output.mode = WD_COOLDOWN;
        wd_output.elapsed = wd_state.elapsed;
        wd_output.high_cycles = 0;
        wd_output.low_cycles = 0;

        wd_output.dipole_a_m2 = (adcs_vec3_t){0};
        wd_output.torque_nm = (adcs_vec3_t){0};
        wd_output.saturation_mask = 0;

        if (wd_state.elapsed >= wd_config.cooldown_cycles) {
            wd_state.mode = WD_OFF;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
            wd_output.mode = WD_OFF;
            wd_output.elapsed = 0;
            wd_output.high_cycles = 0;
            wd_output.low_cycles = 0;
            // Torque/Dipole already zeroed
        }
        break;

    case WD_FAULT:
        wd_output.mode = WD_FAULT;
        break;
}

