    // Therefore, this is a SUBSEQUENT call, not an entry call.
    // EXCEPT: What if the state machine logic was structured differently?
    // My structure: Check transitions based on OLD state. Update NEXT state.
    // If OLD state was DUMPING, we enter this block.
    // Is it possible to re-enter DUMPING? No, once in DUMPING you go to COOLDOWN or stay.
    // So if we are in this block, it is definitely a subsequent call.
    // Thus, elapsed should be incremented.

    new_elapsed++;

    // Low evidence logic
    if (mag_perp > wd_config.stop_nms) {
        new_low_cycles = 0;
    } else {
        if (new_elapsed >= wd_config.minimum_dump_cycles) {
            new_low_cycles++;
        }
    }

    if (new_low_cycles >= wd_config.required_low) {
        next_mode = WD_COOLDOWN;
        new_low_cycles = 0;
        new_elapsed = 0;
    }
} else if (wd_state.mode == WD_COOLDOWN) {
    // Similar to DUMPING, if we are here, old mode was COOLDOWN.
    // So it's a subsequent call.
    new_elapsed++;

    if (new_elapsed >= wd_config.cooldown_cycles) {
        next_mode = WD_OFF;
        new_elapsed = 0;
        new_high_cycles = 0;
        new_low_cycles = 0;
    }
}

// If we transitioned TO DUMPING or COOLDOWN in the blocks above,
// the counters were reset. The command generation happens below based on NEXT_MODE.

// Update State
wd_state.mode = next_mode;
wd_state.high_cycles = new_high_cycles;
wd_state.low_cycles = new_low_cycles;
wd_state.elapsed = new_elapsed;

// Populate Output
wd_output.mode = next_mode;
wd_output.momentum_nms = h_total;
wd_output.parallel_momentum_nms = h_parallel;
wd_output.dumpable_momentum_nms = h_perp;
wd_output.dumpable_magnitude_nms = mag_perp;
wd_output.high_cycles = new_high_cycles;
wd_output.low_cycles = new_low_cycles;
wd_output.elapsed = new_elapsed;

// Generate Commands based on NEXT_MODE
if (next_mode == WD_DUMPING) {
    adcs_status_t st = adcs_momentum_unload_dipole(&h_perp, wd_input.field_body_t, 
                                                   wd_config.gain_s_inv, 
                                                   wd_config.max_dipole_a_m2, 
                                                   &cmd, &achievable_torque);
    if (st != ADCS_OK) {
         cmd.command = (adcs_vec3_t){0,0,0};
         achievable_torque = (adcs_vec3_t){0,0,0};
    }
    sat_mask = cmd.saturated_axes;
} else {
    // OFF, ARMING, COOLDOWN, FAULT -> Zero command
    cmd.command = (adcs_vec3_t){0,0,0};
    cmd.saturated_axes = 0U;
    sat_mask = 0U;
    // Torque remains 0
}

wd_output.dipole_a_m2 = cmd.command;
wd_output.torque_nm = achievable_torque;
wd_output.saturation_mask = sat_mask;
